package dev.eugheist.ttmodern;
import net.minecraft.world.item.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.entity.*;
import thaumcraft.api.aspects.*;
public final class BlockTalisman extends Item implements baubles.api.IBauble {
 static final net.neoforged.neoforge.registries.DeferredItem<BlockTalisman> ITEM=KamiRegistries.ITEMS.register("block_talisman",BlockTalisman::new);
 public BlockTalisman(){super(new Properties().stacksTo(1).rarity(Rarity.EPIC));}
 static void init(){}
 static net.minecraft.nbt.CompoundTag data(ItemStack s){return s.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();}
 public static net.minecraft.world.level.block.Block block(ItemStack s){var id=net.minecraft.resources.ResourceLocation.tryParse(data(s).getString("blockName"));return id==null?net.minecraft.world.level.block.Blocks.AIR:net.minecraft.core.registries.BuiltInRegistries.BLOCK.get(id);}
 public static int count(ItemStack s){return Math.max(0,data(s).getInt("blockCount"));}
 public static boolean active(ItemStack s){return data(s).getBoolean("active");}
 static void count(ItemStack s,int value){CustomData.update(DataComponents.CUSTOM_DATA,s,t->t.putInt("blockCount",Math.max(0,value)));}
 public static int remove(ItemStack s,int amount){int take=Math.min(count(s),Math.max(0,amount));count(s,count(s)-take);return take;}
 static boolean bind(ItemStack s,net.minecraft.world.level.block.Block b){if(block(s)!=net.minecraft.world.level.block.Blocks.AIR&&count(s)>0)return false;CustomData.update(DataComponents.CUSTOM_DATA,s,t->t.putString("blockName",net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(b).toString()));return true;}
 @Override public baubles.api.BaubleType getBaubleType(ItemStack s){return baubles.api.BaubleType.RING;}
 @Override public net.minecraft.world.InteractionResultHolder<ItemStack> use(net.minecraft.world.level.Level level,net.minecraft.world.entity.player.Player p,net.minecraft.world.InteractionHand hand){var s=p.getItemInHand(hand);if(p.isShiftKeyDown()&&block(s)!=net.minecraft.world.level.block.Blocks.AIR){CustomData.update(DataComponents.CUSTOM_DATA,s,t->t.putBoolean("active",!active(s)));p.playSound(net.minecraft.sounds.SoundEvents.EXPERIENCE_ORB_PICKUP,.3f,.1f);return net.minecraft.world.InteractionResultHolder.sidedSuccess(s,level.isClientSide);}return net.minecraft.world.InteractionResultHolder.pass(s);}
 @Override public net.minecraft.world.InteractionResult useOn(net.minecraft.world.item.context.UseOnContext context){var s=context.getItemInHand();var p=context.getPlayer();var level=context.getLevel();if(p==null)return net.minecraft.world.InteractionResult.PASS;if(!level.mayInteract(p,context.getClickedPos())||!p.mayUseItemAt(context.getClickedPos(),context.getClickedFace(),s))return net.minecraft.world.InteractionResult.FAIL;if(level.isClientSide)return net.minecraft.world.InteractionResult.SUCCESS;if(bind(s,level.getBlockState(context.getClickedPos()).getBlock()))return net.minecraft.world.InteractionResult.CONSUME;var item=block(s).asItem();if(item==Items.AIR||count(s)==0)return net.minecraft.world.InteractionResult.PASS;var handler=level.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,context.getClickedPos(),context.getClickedFace());if(handler!=null){for(int slot=0;slot<handler.getSlots()&&count(s)>0;slot++){var offered=new ItemStack(item,Math.min(count(s),item.getDefaultMaxStackSize()));var rest=handler.insertItem(slot,offered,false);remove(s,offered.getCount()-rest.getCount());}return net.minecraft.world.InteractionResult.CONSUME;}var placed=new ItemStack(item);var result=placed.useOn(new net.minecraft.world.item.context.UseOnContext(level,p,context.getHand(),placed,new net.minecraft.world.phys.BlockHitResult(context.getClickLocation(),context.getClickedFace(),context.getClickedPos(),context.isInside())));if(result.consumesAction())remove(s,1);return result;}
 @Override public void onWornTick(ItemStack s,LivingEntity wearer){if(wearer.level().isClientSide||!active(s)||!(wearer instanceof net.minecraft.world.entity.player.Player p))return;var item=block(s).asItem();if(item==Items.AIR)return;var inv=p.getInventory();int highest=-1;boolean free=false;for(int i=0;i<36;i++){var stack=inv.getItem(i);if(stack.isEmpty()){free=true;continue;}if(stack.is(item)&&(highest==-1||highest>8&&stack.getCount()>inv.getItem(highest).getCount()))highest=i;}if(highest==-1){var held=p.getMainHandItem();if(free&&(held.isEmpty()||held.is(item))){int amount=Math.min(64,count(s));if(amount>0){var stack=new ItemStack(item,amount);inv.add(stack);remove(s,amount-stack.getCount());}}}else{long stored=count(s);for(int i=0;i<36;i++){var stack=inv.getItem(i);if(i==highest||!stack.is(item))continue;if(stored+stack.getCount()>Integer.MAX_VALUE)continue;stored+=stack.getCount();inv.setItem(i,ItemStack.EMPTY);}count(s,(int)stored);var stack=inv.getItem(highest);stack.grow(remove(s,stack.getMaxStackSize()-stack.getCount()));}inv.setChanged();}
 @Override public void appendHoverText(ItemStack s,TooltipContext context,java.util.List<net.minecraft.network.chat.Component> lines,TooltipFlag flag){if(block(s)!=net.minecraft.world.level.block.Blocks.AIR)lines.add(net.minecraft.network.chat.Component.translatable(block(s).getDescriptionId()).append(" (x"+count(s)+")"));lines.add(net.minecraft.network.chat.Component.translatable(active(s)?"ttmisc.active":"ttmisc.inactive"));}
 static void research(){var r=new KamiResearch("BLOCK_TALISMAN",new AspectList().add(Aspect.VOID,2).add(Aspect.DARKNESS,1).add(Aspect.ELDRITCH,1).add(Aspect.MAGIC,1),14,17,5,new ItemStack(ITEM.get()));r.setParents("ICHOR_PICK_GEM","ICHOR_SHOVEL_GEM");r.setPages(new thaumcraft.api.research.ResearchPage("ttresearch.page.BLOCK_TALISMAN.0"),MagnetResearch.page("BLOCK_TALISMAN",thaumcraft.api.research.ResearchPage.PageType.INFUSION_CRAFTING)).registerResearchItem();ThaumicTinkererModern.INFUSION_RECIPES.add(new dev.eugheist.tc4modern.InfusionItemRecipes.Recipe("BLOCK_TALISMAN","BLOCK_TALISMAN",ITEM::get,9,new AspectList().add(Aspect.VOID,65).add(Aspect.DARKNESS,32).add(Aspect.MAGIC,50).add(Aspect.ELDRITCH,32),()->FocusResearch.item("focus_portable_hole"),java.util.List.of(()->KamiResources.item(KamiResources.Kind.ICHOR),()->Items.ENDER_CHEST,()->Items.DIAMOND,()->KamiResources.item(KamiResources.Kind.ICHOR),()->FocusResearch.item("tainted_goo"),()->FocusResearch.item("void_jar"))));}
}
